from typing import Annotated
from fastapi import Depends


def pagination(skip: int = 0, limit: int = 20):
    return {"skip": skip, "limit": limit}


@app.get("/items")
def list_items(page: Annotated[dict, Depends(pagination)]):
    return page

from sqlalchemy.orm import Session

def get_db():
    db = SessionLocal()
    try:
        yield db
    finally:
        db.close()


@app.get("/users")
def users(db: Annotated[Session, Depends(get_db)]):
    return db.query(User).all()

from fastapi import HTTPException

@app.get("/items/{item_id}")
def read_item(item_id: int):
    if item_id not in db:
        raise HTTPException(status_code=404, detail="Item not found")
    return db[item_id]

from fastapi import Request
from fastapi.responses import JSONResponse


class OutOfStock(Exception):
    pass


@app.exception_handler(OutOfStock)
async def out_of_stock_handler(request: Request, exc: OutOfStock):
    return JSONResponse(status_code=409, content={"detail": "Out of stock"})

